def make(qid_num, category, subcategory, skills, prompt, opts, correct, explanation, steps, diff=3, family=None):
    ids='abcd'
    options=[{'id':ids[i],'text':t,'is_correct':ids[i]==correct,'distractor_type':('plausible_near_miss' if ids[i]!=correct else None)} for i,t in enumerate(opts)]
    qid=f'q_v8_{qid_num:04d}'
    return {
      'id':qid,'category':category,'subcategory':subcategory,'skills':skills,'content_type':'textual','prompt':prompt,
      'options':options,'correct_option_id':correct,'explanation':explanation,'reasoning_steps':steps,
      'visual_schema':None,'formal_spec':None,'difficulty_prior':diff,'difficulty_calibrated':diff,
      'mode_compatibility':['training','simulation'],'prerequisite_knowledge':[],
      'template_id':f'tmpl_v8_{category}_{subcategory}','instance_id':qid,
      'semantic_family_id':family or f'v8_{category}_{subcategory}_{qid_num}', 'generation_type':'manual_v8',
      'validation':{
        'structural_validation':True,
        'logical_validation':{'applicable':False,'status':'not_applicable','detail':'Semantic/content question; no formal checker applicable.'},
        'content_quality_validation':True,
        'semantic_review':{'required':True,'status':'approved_v8','reviewer':'content_review_v8','notes':'Original v8 content reviewed for clarity and single best answer.'},
        'difficulty_calibration':{'status':'calibrated_v8','sample_size':0,'observed_p_value':None,'flag_mismatch':False},
        'approved_for_pool':True},
      'provenance':{'source':'v8_original','legacy_gold':False},
      'usage_stats':{'times_shown':0,'times_correct':0,'times_wrong':0,'avg_time_seconds':0,'last_shown_at':None},
      'hint':''
    }

